/**
 * Return the previous/next element of a list.
 *
 * @param {array} list    The list of elements
 * @param activeElement   The active element
 * @param shouldGetNext   Choose to get next or previous element
 * @param isCycleAllowed
 * @return {Element|elem} The proper element
 */
const getNextActiveElement = (list, activeElement, shouldGetNext, isCycleAllowed) => {
  const listLength = list.length
  let index = list.indexOf(activeElement)

  // if the element does not exist in the list return an element
  // depending on the direction and if cycle is allowed
  if (index === -1) {
    return !shouldGetNext && isCycleAllowed ? list[listLength - 1] : list[0]
  }

  let steps = 0
  let nextIndex = index
  while (steps < listLength) {
    nextIndex += shouldGetNext ? 1 : -1
    if (isCycleAllowed) {
      nextIndex = (nextIndex + listLength) % listLength
    } else {
      if (nextIndex < 0 || nextIndex >= listLength) {
        // reached end without cycling
        break
      }
    }
    if (!isDisabled(list[nextIndex])) {
      return list[nextIndex]
    }
    steps++
  }
  // fallback: return original element
  return list[index]
}
